def get_valid_consensus_hashes( self, block_id ):
        """
        Get the list of valid consensus hashes for a given block.
        """
        if block_id is None:
            raise ValueError( "block_id is required." )

        valid_consensus_hashes = self.get_valid_consensus_hashes_for_block( block_id )
        if valid_consensus_hashes is None:
            return []
        else:
            return valid_consensus_hashes.split( ',' )

